import { create_teams } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    groupDialog: Boolean
  },
  data() {
    return {
      loading: false,
      groupchatname: "",
      description: "",
      dashboard_type: "",
      Password: "",
      broadcastType: null,
      sourceInfo: "",
      imageUrl: ""
    };
  },
  watch: {
    groupDialog: {
      async handler() {
        if (this.groupDialog == true) {
          // console.log(this.broadcastType);
          // this.broadcastType = "";
        }
      },
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$refs.form.reset();
      this.$emit("clicked", 0);
    },
    validateURL(url) {
      if (url != "") {
        const urlRegex = /^(ftp|http|https):\/\/[^ "]+$/;
        return urlRegex.test(url);
      }
    },
    validate_data() {
      if (this.$refs.form.validate()) {
        this.create_teams_message();
      }
    },
    async create_teams_message() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(create_teams, {
          input: {
            organization_id: data.organization.organization_id,
            team_name: this.groupchatname,
            team_description: this.description,
            team_owner_id: data.user.user_id,
            user_email_id: data.user.user_email_id
          }
        }));
        var response = JSON.parse(result.data.create_teams);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsggroup", response.Message);
          this.$refs.form.reset();
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.$emit("errorMsg", error.errors[0].message);
        this.loading = false;
      }
    }
  }
};
